allocator_usable_size_probe.source:
use std::alloc::{alloc, dealloc, Layout};
use std::collections::BTreeMap;
unsafe extern "C" { fn malloc_size(ptr: *const std::ffi::c_void) -> usize; }
fn main() {
 for requested in [72,80] {
  let layout=Layout::from_size_align(requested,8).unwrap();
  let pointers:Vec<_>=(0..10_000).map(|_|unsafe { alloc(layout) }).collect();
  let mut counts=BTreeMap::new();
  for &p in &pointers { assert!(!p.is_null()); *counts.entry(unsafe{malloc_size(p.cast())}).or_insert(0usize)+=1; }
  println!("requested={requested} usable_size_counts={counts:?}");
  for p in pointers { unsafe {dealloc(p,layout)}; }
 }
}
